#include <iostream>
#include <string>
using namespace std;

int main() {
    const int MOD = 1000003;
    string s;
    cin >> s;

    long long result = 0;
    for (char ch : s) {
        int value;
        switch (ch) {
            case '>': value = 8;  break;
            case '<': value = 9;  break;
            case '+': value = 10; break;
            case '-': value = 11; break;
            case '.': value = 12; break;
            case ',': value = 13; break;
            case '[': value = 14; break;
            case ']': value = 15; break;
            default: continue;
        }
        result = (result * 16 + value) % MOD;
    }

    cout << result << '\n';
    return 0;
}

